아래에서 시작 위치와 학습률을 바꾸어 결과를 확인한다. 다음 스텝은 한 번 갱신하고, 재생은 갱신을 반복한다.

viewof gdEta = Inputs.range([0.05, 1.1], { step: 0.05, label: "학습률 η", value: 0.1 })
viewof gdInit = Inputs.range([-1, 7], { step: 0.5, label: "시작 w", value: 5 })
















mutable gdStep = 0
mutable gdPlaying = false
gdMax = 25
viewof gdCtl = Inputs.button([
  ["▸ 다음 스텝", () =&gt; { mutable gdPlaying = false; if (gdStep &lt; gdMax) mutable gdStep = gdStep + 1; return gdStep }],
  ["▶ 재생", () =&gt; { mutable gdPlaying = true; return gdStep }],
  ["↺ 처음으로", () =&gt; { mutable gdPlaying = false; mutable gdStep = 0; return 0 }]
])






























gdReset = { gdEta; gdInit; mutable gdPlaying = false; mutable gdStep = 0; return true }







gdPlayer = {
  if (!gdPlaying) return false
  while (gdPlaying && gdStep &lt; gdMax) {
    await Promises.delay(700)
    mutable gdStep = gdStep + 1
    yield true
  }
  mutable gdPlaying = false
  return false
}







gdPath = {
  let w = gdInit
  const path = []
  for (let i = 0; i &lt;= gdMax; i++) {
    path.push({ step: i, w, f: (w - 3) ** 2, g: 2 * (w - 3) })
    w = w - gdEta * 2 * (w - 3)
  }
  return path
}
gdCur = gdPath[Math.min(gdStep, gdMax)]
gdShown = gdPath.slice(0, Math.min(gdStep, gdMax) + 1)
gdTan = [gdCur.w - 1.2, gdCur.w + 1.2].map(w =&gt; ({ w, f: gdCur.f + gdCur.g * (w - gdCur.w) }))
































Plot.plot({
  width: 470, height: 340,
  style: { fontFamily: "Pretendard, sans-serif", fontSize: "12px" },
  x: { label: "w", domain: [-1, 7], grid: true },
  y: { label: "f(w) = (w − 3)²", domain: [-1, 16], grid: true },
  marks: [
    Plot.line(dvCurve, { x: "w", y: "f", stroke: "#ccc", strokeWidth: 2 }),
    Plot.line(gdTan, { x: "w", y: "f", stroke: "#1565C0", strokeWidth: 2, strokeDasharray: "6,3" }),
    Plot.line(gdShown, { x: "w", y: "f", stroke: "#8C1515", strokeWidth: 1.5, strokeDasharray: "4,2" }),
    Plot.dot(gdShown, { x: "w", y: "f", fill: "#8C1515", r: 4, stroke: "white", strokeWidth: 1.5, opacity: 0.6 }),
    Plot.dot([gdCur], { x: "w", y: "f", fill: "#C62828", r: 8, stroke: "white", strokeWidth: 2 }),
    Plot.arrow(gdStep &lt; gdMax ? [{ x1: gdCur.w, y1: gdCur.f, x2: gdCur.w - gdEta * gdCur.g, y2: gdCur.f }] : [], { x1: "x1", y1: "y1", x2: "x2", y2: "y2", stroke: "#2E7D32", strokeWidth: 2.5, headLength: 7 }),
    Plot.dot([{ w: 3, f: 0 }], { x: "w", y: "f", fill: "#D4A017", r: 8, symbol: "star", stroke: "white", strokeWidth: 1.5 }),
    Plot.text([null], { text: () =&gt; "★ 최솟값 w = 3", x: 3, y: 0, dy: 18, fill: "#D4A017", fontSize: 10, fontWeight: "600" }),
    Plot.text([null], { text: () =&gt; `스텝 ${gdStep}`, frameAnchor: "top-left", fill: "#333", fontSize: 13, fontWeight: "700", dx: 10, dy: 12 })
  ]
})








