    w ← ${gdCur.w.toFixed(3)} − ${gdEta.toFixed(2)} × (${gdCur.g.toFixed(3)}) = &lt;strong&gt;${(gdCur.w - gdEta * gdCur.g).toFixed(4)}&lt;/strong&gt;
